using Mutagen.Bethesda; using Mutagen.Bethesda.Plugins; using SFRecordCompareEngine.Core.DTOs.Records; using SFRecordCompareEngine.Core.DTOs.Results; using SFRecordCompareEngine.Core.Helpers; using SFRecordCompareEngine.Core.Importers.Interfaces; using SFRecordCompareEngine.Core.Repositories.Interfaces;
namespace SFRecordCompareEngine.Core.Importers.Starfield;
public class MiscObjectImporter : ITypedRecordDetailImporter { private readonly IMiscObjectRepository Repository; public GameRelease GameRelease => GameRelease.Starfield; public RecordType RecordType => new(RecordTypeCatalog.MiscObject.RecordID); public string TableName => RecordTypeCatalog.MiscObject.TableName; public MiscObjectImporter(IMiscObjectRepository repository) { Repository = repository; } public void Import(object recordDTO, RecordTypeImportResultDTO resultDTO) { var record = (MiscObjectDTO)recordDTO; record.ImportedAtUTC = DateTime.UtcNow; Repository.Save(record); resultDTO.DetailRowsImported++; } }
